<?php

defined('BASEPATH') or exit('No direct script access allowed');
/** Dedicated own calendar; never delegates to the legacy calendar/event/reminder controller. */
class Company_calendar extends AdminController
{
    public function index()
    {
        if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto indisponível.',503);return;}
        require_once APPPATH.'services/CompanyCalendarRead.php';require_once APPPATH.'services/CompanyCalendarPresentation.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$this->output->set_header('Cache-Control: no-store');$this->output->set_header('X-Content-Type-Options: nosniff');
        try{
            $preferences=new CompanyCalendarPreferences($this->db,db_prefix());$verb=strtoupper($this->input->method(true));$csrf=$this->session->userdata('company_calendar_csrf');if(!is_string($csrf)||!preg_match('/^[a-f0-9]{64}$/D',$csrf)){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_calendar_csrf',$csrf);}
            if($verb==='POST'){$post=$this->input->post(null,false);$frameworkCsrf=$this->security->get_csrf_token_name();if(!is_array($post)||array_diff(array_keys($post),['company_calendar_csrf','_company_context','revision','settings',$frameworkCsrf])||!is_string($post['company_calendar_csrf']??null)||!hash_equals($csrf,$post['company_calendar_csrf'])){show_error('Recarregue antes de salvar.',403);return;}$revision=$post['revision']??null;if(!is_string($revision)||!preg_match('/^(?:0|[1-9][0-9]{0,9})$/D',$revision)||!is_array($post['settings']??null))throw new DomainException('company_calendar_preferences_invalid');$preferences->save($issuer,$actor,(int)$revision,$post['settings']);CompanyRequestScope::invalidateCaches($this);redirect(CompanyRequestScope::adminUrl($this,'company_calendar'),'location',303);return;}
            if(!in_array($verb,['GET','HEAD'],true)){show_error('Método não permitido.',405);return;}$query=$this->input->get(null,false);if(!is_array($query)||array_diff(array_keys($query),['anchor','view','start','end','client_id','title','sources','sources_present','format','_company_context']))throw new DomainException('company_calendar_invalid');$pref=$preferences->page($issuer,$actor);$view=$query['view']??$pref['values']['default_view_calendar'];$anchor=$query['anchor']??gmdate('Y-m-d');if(!is_string($view)||!is_string($anchor))throw new DomainException('company_calendar_invalid');$range=CompanyCalendarPresentation::range($anchor,$view,(int)$pref['values']['calendar_first_day']);$format=$query['format']??'html';if(!in_array($format,['html','json'],true))throw new DomainException('company_calendar_invalid');$filter=['start'=>$query['start']??$range['start'],'end'=>$query['end']??$range['end'],'client_id'=>$query['client_id']??'','title'=>$query['title']??''];if(array_key_exists('sources',$query)||array_key_exists('sources_present',$query))$filter['sources']=$query['sources']??[];
            $reader=new CompanyCalendarRead($this->db,db_prefix());$calendar=$reader->page($issuer,$actor,$filter);if($calendar['revision']!==$pref['revision']||$calendar['preferences']!==$pref['values'])throw new DomainException('company_calendar_stale');
            if($format==='json'){$body=json_encode($calendar,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$reader->confirm($issuer,$actor);$this->output->set_content_type('application/json');$this->output->set_output($body);return;}
            // HTML uses its exact computed range; custom API ranges cannot silently change the grid.
            if($calendar['filters']['start']!==$range['start']||$calendar['filters']['end']!==$range['end'])throw new DomainException('company_calendar_invalid');$acl=new IssuerResourceAccess($this->db,db_prefix());$configure=$acl->can($issuer,$actor,'calendar','configure')&&$acl->can($issuer,$actor,'settings','view')&&$acl->can($issuer,$actor,'settings','edit');$canFilter=$acl->can($issuer,$actor,'customers','view');$body=$this->load->view('admin/companies/calendar',['issuer'=>$issuer,'actor'=>$actor,'calendar'=>$calendar,'calendar_view'=>$view,'calendar_anchor'=>$anchor,'calendar_range'=>$range,'calendar_csrf'=>$csrf,'can_configure'=>$configure,'can_filter_clients'=>$canFilter],true);$reader->confirm($issuer,$actor);if($configure!==($acl->can($issuer,$actor,'calendar','configure')&&$acl->can($issuer,$actor,'settings','view')&&$acl->can($issuer,$actor,'settings','edit'))||$canFilter!==$acl->can($issuer,$actor,'customers','view'))throw new DomainException('company_calendar_stale');$this->output->set_output($body);
        }catch(DomainException $e){log_message('error','Company calendar rejected ['.(preg_match('/^(?:company|issuer|asaas|bb)_[a-z_]{1,80}$/D',$e->getMessage())?$e->getMessage():'unclassified_domain').'].');$status=match($e->getMessage()){'company_calendar_denied'=>403,'company_calendar_stale','company_calendar_preferences_stale'=>409,'company_calendar_source_unavailable'=>503,default=>422};show_error($status===409?'O calendário ou as permissões mudaram. Recarregue antes de continuar.':($e->getMessage()==='company_calendar_limit'?'Reduza o intervalo ou selecione menos fontes. O calendário não foi truncado.':'Não foi possível confirmar o calendário desta empresa.'),$status);}
        catch(Throwable $e){$chain=[];$cause=$e;for($depth=0;$cause!==null&&$depth<3;$depth++,$cause=$cause->getPrevious()){$code=(string)$cause->getCode();$chain[]=get_class($cause).'@'.basename($cause->getFile()).':'.$cause->getLine().':'.(preg_match('/^[A-Z0-9]{1,8}$/D',$code)?$code:'unknown');}log_message('error','Company calendar response unconfirmed ['.implode(' <- ',$chain).']; no messages or contents logged.');show_error('Calendário indisponível. Nenhum conteúdo foi confirmado.',503);}
    }
}
